// Package gen is the flow every kit generator shares (gen-retro-index, gen-lint-index,
// gen-build-state, kit-state): the `[--check] [<kit-root>]` command line, the kit sub-directory
// guard, the GENERATED first line, and writing a generated file atomically. Each generator only
// renders its content; the messages and exit codes live here once.
package gen

import (
	"fmt"
	"io"
	"os"
	"os/exec"
	"strings"

	"github.com/angeles725/niagara-tools/go/internal/cli"
)

// GeneratedLine is line 1 of every file kit-state generates (BUILD-STATE.md, retros/INDEX.md). Those
// files are not committed (.gitignore): the .githooks post-merge/post-checkout/post-rewrite hooks
// regenerate them, and every parser of them skips this HTML comment like any non-row, non-envelope line.
const GeneratedLine = "<!-- GENERATED by kit-state from ledger.d/ and retros/ — do not edit; regenerated on pull -->"

// Exit codes shared by the generators (the gen-retro-index contract).
const (
	ExitOK    = 0 // file written, or the inputs are valid under --check
	ExitStale = 1 // an input violation (a fragment, source or header); nothing written
	ExitEnv   = 3 // usage or environment error; nothing written
)

// ParseArgs reads `[--check] [<kit-root>]` for tool. With no root argument (an empty one counts as
// none, as the bash tools did) the root is the rootEnv variable the toolbelt wrapper exports. On a
// usage error or no root it prints why to s.Err and returns ok false: exit ExitEnv.
func ParseArgs(tool, rootEnv string, args []string, s cli.Stdio) (check bool, root string, ok bool) {
	for _, a := range args {
		switch {
		case a == "--check":
			check = true
		case strings.HasPrefix(a, "-") || root != "":
			fmt.Fprintf(s.Err, "usage: %s.sh [--check] [<kit-root>]\n", tool)
			return false, "", false
		default:
			root = a
		}
	}
	if root == "" {
		if root = s.Env(rootEnv); root == "" {
			fmt.Fprintf(s.Err, "%s: no <kit-root> given and %s is unset (run toolbelt/%s.sh)\n", tool, rootEnv, tool)
			return false, "", false
		}
	}
	return check, root, true
}

// SubDir is root/sub when it is a directory; otherwise it prints "no <sub>/ under <root>" to s.Err
// and returns ok false: exit ExitEnv.
func SubDir(tool, root, sub string, s cli.Stdio) (string, bool) {
	dir := root + "/" + sub
	if !IsDir(dir) {
		fmt.Fprintf(s.Err, "%s: no %s/ under %s\n", tool, sub, root)
		return "", false
	}
	return dir, true
}

// IsRegular reports whether path is a regular file (symlinks followed).
func IsRegular(path string) bool {
	st, err := os.Stat(path)
	return err == nil && st.Mode().IsRegular()
}

// IsDir reports whether path is a directory (symlinks followed).
func IsDir(path string) bool {
	st, err := os.Stat(path)
	return err == nil && st.IsDir()
}

// File is one generated file: what a generator rendered and where it is written. The generated kit
// files are not committed (R10-D1), so there is no committed copy to compare with: a generator's
// --check validates its inputs, and a write always goes through a temporary file in the target's
// directory, keeping the target's mode, so a failed write never leaves a truncated file behind.
type File struct {
	Tool    string // command name; prefixes every message
	Path    string
	Content string // the exact bytes a write stores
}

// Write writes f atomically and returns the exit code: ExitOK and "<tool>: wrote <path>", or ExitEnv.
func (f File) Write(s cli.Stdio) int {
	if err := writeAtomic(f.Path, f.Content); err != nil {
		fmt.Fprintf(s.Err, "%s: cannot write %s: %v\n", f.Tool, f.Path, err)
		return ExitEnv
	}
	fmt.Fprintf(s.Out, "%s: wrote %s\n", f.Tool, f.Path)
	return ExitOK
}

// writeAtomic replaces path through a temporary file in its directory, so a failed write never
// leaves a truncated file behind.
func writeAtomic(path, content string) error {
	mode := os.FileMode(0o644)
	if st, err := os.Stat(path); err == nil {
		mode = st.Mode().Perm()
	}
	tmp := fmt.Sprintf("%s.tmp.%d", path, os.Getpid())
	if err := os.WriteFile(tmp, []byte(content), mode); err != nil {
		_ = os.Remove(tmp)
		return err
	}
	if err := os.Rename(tmp, path); err != nil {
		_ = os.Remove(tmp)
		return err
	}
	return nil
}

// ShowDiff writes `diff - <path>` (generated vs committed, POSIX normal format) to w; it is
// diagnostic only, so a missing diff binary prints nothing.
func ShowDiff(generated, path string, w io.Writer) {
	cmd := exec.Command("diff", "-", path)
	cmd.Stdin = strings.NewReader(generated)
	cmd.Stdout, cmd.Stderr = w, w
	_ = cmd.Run()
}
